CREATE DATABASE IF NOT EXISTS wateq_hr CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE wateq_hr;

CREATE TABLE roles (id TINYINT UNSIGNED PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, code VARCHAR(30) NOT NULL UNIQUE);
CREATE TABLE permissions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(80) NOT NULL UNIQUE, label VARCHAR(100) NOT NULL);
CREATE TABLE role_permissions (role_id TINYINT UNSIGNED NOT NULL, permission_id INT UNSIGNED NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(permission_id) REFERENCES permissions(id));
CREATE TABLE branches (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, city VARCHAR(100), address VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE departments (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, branch_id INT UNSIGNED NULL, name VARCHAR(120) NOT NULL UNIQUE, manager_employee_id INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL);
CREATE TABLE grades (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, description VARCHAR(255));
CREATE TABLE job_titles (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, department_id INT UNSIGNED NULL, grade_id INT UNSIGNED NULL, name VARCHAR(120) NOT NULL UNIQUE, FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL, FOREIGN KEY(grade_id) REFERENCES grades(id) ON DELETE SET NULL);
CREATE TABLE employees (
 id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employee_no VARCHAR(30) NOT NULL UNIQUE, first_name VARCHAR(80) NOT NULL, father_name VARCHAR(80), last_name VARCHAR(80) NOT NULL,
 national_id VARCHAR(30) UNIQUE, nationality VARCHAR(80), gender ENUM('male','female'), birth_date DATE, phone VARCHAR(30), email VARCHAR(190) UNIQUE, address VARCHAR(255),
 branch_id INT UNSIGNED NULL, department_id INT UNSIGNED NULL, job_title_id INT UNSIGNED NULL, manager_id INT UNSIGNED NULL, hired_at DATE NOT NULL,
 contract_type VARCHAR(80), base_salary DECIMAL(12,2) NOT NULL DEFAULT 0, allowances DECIMAL(12,2) NOT NULL DEFAULT 0,
 status ENUM('active','leave','suspended','resigned','terminated') NOT NULL DEFAULT 'active', left_on DATE NULL, photo_path VARCHAR(255), notes TEXT,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 INDEX(status), INDEX(department_id), INDEX(last_name,first_name),
 FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL, FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL,
 FOREIGN KEY(job_title_id) REFERENCES job_titles(id) ON DELETE SET NULL, FOREIGN KEY(manager_id) REFERENCES employees(id) ON DELETE SET NULL
);
ALTER TABLE departments ADD CONSTRAINT fk_department_manager FOREIGN KEY(manager_employee_id) REFERENCES employees(id) ON DELETE SET NULL;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employee_id INT UNSIGNED NULL UNIQUE, role_id TINYINT UNSIGNED NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, totp_secret VARCHAR(64) NULL, mfa_enabled TINYINT(1) NOT NULL DEFAULT 0, active TINYINT(1) NOT NULL DEFAULT 1, failed_attempts TINYINT UNSIGNED NOT NULL DEFAULT 0, locked_until DATETIME NULL, last_login_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE SET NULL, FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE mfa_recovery_codes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, code_hash VARCHAR(255) NOT NULL, used_at DATETIME NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE password_resets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, used_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE shifts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, starts_at TIME NOT NULL, ends_at TIME NOT NULL, work_days VARCHAR(20) NULL, grace_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 10, active TINYINT(1) NOT NULL DEFAULT 1);
CREATE TABLE employee_shifts (employee_id INT UNSIGNED NOT NULL, shift_id INT UNSIGNED NOT NULL, effective_from DATE NOT NULL, PRIMARY KEY(employee_id,effective_from), FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE, FOREIGN KEY(shift_id) REFERENCES shifts(id));
CREATE TABLE company_holidays (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(150) NOT NULL, starts_on DATE NOT NULL, ends_on DATE NOT NULL, branch_id INT UNSIGNED NULL, is_day_off TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(starts_on,ends_on), FOREIGN KEY(branch_id) REFERENCES branches(id) ON DELETE SET NULL);
CREATE TABLE attendance (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employee_id INT UNSIGNED NOT NULL, shift_id INT UNSIGNED NULL, work_date DATE NOT NULL, check_in DATETIME NULL, check_out DATETIME NULL, status ENUM('present','late','absent','leave') NOT NULL DEFAULT 'present', late_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 0, early_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 0, overtime_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 0, notes VARCHAR(255), recorded_by INT UNSIGNED NULL, UNIQUE(employee_id,work_date), INDEX(work_date,status), FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE, FOREIGN KEY(shift_id) REFERENCES shifts(id) ON DELETE SET NULL, FOREIGN KEY(recorded_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE attendance_corrections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employee_id INT UNSIGNED NOT NULL, work_date DATE NOT NULL, check_in TIME NOT NULL, check_out TIME NULL, reason VARCHAR(500) NOT NULL, status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', decided_by INT UNSIGNED NULL, decided_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(status,work_date), FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE, FOREIGN KEY(decided_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE service_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employee_id INT UNSIGNED NOT NULL, kind ENUM('salary_letter','experience_letter','contact_change') NOT NULL, payload JSON NULL, result_snapshot JSON NULL, status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending', decided_by INT UNSIGNED NULL, decided_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(status,created_at), FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE, FOREIGN KEY(decided_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE workflow_tasks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employee_id INT UNSIGNED NOT NULL, phase ENUM('onboarding','offboarding') NOT NULL, title VARCHAR(160) NOT NULL, due_on DATE NULL, completed_at DATETIME NULL, completed_by INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(employee_id,phase,title), FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE, FOREIGN KEY(completed_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE leave_types (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE, annual_days DECIMAL(6,2) NOT NULL DEFAULT 0, count_mode ENUM('calendar','workdays') NOT NULL DEFAULT 'calendar', paid TINYINT(1) NOT NULL DEFAULT 1, requires_attachment TINYINT(1) NOT NULL DEFAULT 0);
CREATE TABLE leave_balances (employee_id INT UNSIGNED NOT NULL, leave_type_id INT UNSIGNED NOT NULL, balance_year SMALLINT UNSIGNED NOT NULL, allocated DECIMAL(7,2) NOT NULL DEFAULT 0, used DECIMAL(7,2) NOT NULL DEFAULT 0, PRIMARY KEY(employee_id,leave_type_id,balance_year), FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE, FOREIGN KEY(leave_type_id) REFERENCES leave_types(id));
CREATE TABLE leave_requests (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employee_id INT UNSIGNED NOT NULL, leave_type_id INT UNSIGNED NOT NULL, starts_on DATE NOT NULL, ends_on DATE NOT NULL, days DECIMAL(7,2) NOT NULL, day_breakdown JSON NULL, reason TEXT, attachment_path VARCHAR(255), status ENUM('pending','approved','rejected','cancelled') NOT NULL DEFAULT 'pending', supervisor_approved_by INT UNSIGNED NULL, decided_by INT UNSIGNED NULL, decided_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(status,starts_on), FOREIGN KEY(employee_id) REFERENCES employees(id), FOREIGN KEY(leave_type_id) REFERENCES leave_types(id), FOREIGN KEY(supervisor_approved_by) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(decided_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE contracts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employee_id INT UNSIGNED NOT NULL, contract_no VARCHAR(60) NOT NULL UNIQUE, type VARCHAR(80) NOT NULL, starts_on DATE NOT NULL, ends_on DATE, salary DECIMAL(12,2) NOT NULL DEFAULT 0, file_path VARCHAR(255), notes TEXT, status ENUM('draft','review','approved') NOT NULL DEFAULT 'draft', version INT UNSIGNED NOT NULL DEFAULT 0, submitted_by INT UNSIGNED NULL, approved_by INT UNSIGNED NULL, approved_at DATETIME NULL, INDEX(ends_on), FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE, FOREIGN KEY(submitted_by) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(approved_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE contract_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, contract_id INT UNSIGNED NOT NULL, version INT UNSIGNED NOT NULL, snapshot JSON NOT NULL, approved_by INT UNSIGNED NULL, approved_at DATETIME NOT NULL, UNIQUE(contract_id,version), FOREIGN KEY(contract_id) REFERENCES contracts(id) ON DELETE CASCADE, FOREIGN KEY(approved_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE documents (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employee_id INT UNSIGNED NOT NULL, title VARCHAR(150) NOT NULL, type VARCHAR(80) NOT NULL, issued_on DATE, expires_on DATE, file_path VARCHAR(255) NOT NULL, notes TEXT, INDEX(expires_on), FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE);
CREATE TABLE salaries (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employee_id INT UNSIGNED NOT NULL, pay_month DATE NOT NULL, base_salary DECIMAL(12,2) NOT NULL DEFAULT 0, allowances DECIMAL(12,2) NOT NULL DEFAULT 0, deductions DECIMAL(12,2) NOT NULL DEFAULT 0, advances DECIMAL(12,2) NOT NULL DEFAULT 0, bonuses DECIMAL(12,2) NOT NULL DEFAULT 0, overtime DECIMAL(12,2) GENERATED ALWAYS AS (base_salary+allowances+bonuses+overtime-deductions-advances) STORED, status ENUM('draft','review','approved','paid') NOT NULL DEFAULT 'draft', submitted_by INT UNSIGNED NULL, approved_by INT UNSIGNED NULL, approved_at DATETIME NULL, paid_at DATETIME NULL, notes TEXT, UNIQUE(employee_id,pay_month), FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE);
CREATE TABLE payroll_periods (pay_month DATE PRIMARY KEY, status ENUM('open','locked') NOT NULL DEFAULT 'open', locked_by INT UNSIGNED NULL, locked_at DATETIME NULL, FOREIGN KEY(locked_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE salary_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, salary_id INT UNSIGNED NOT NULL, label VARCHAR(100) NOT NULL, kind ENUM('earning','deduction') NOT NULL, amount DECIMAL(12,2) NOT NULL, FOREIGN KEY(salary_id) REFERENCES salaries(id) ON DELETE CASCADE);
CREATE TABLE performance_reviews (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employee_id INT UNSIGNED NOT NULL, reviewer_id INT UNSIGNED NULL, period_start DATE NOT NULL, period_end DATE NOT NULL, attendance_score TINYINT UNSIGNED NOT NULL, quality_score TINYINT UNSIGNED NOT NULL, productivity_score TINYINT UNSIGNED NOT NULL, cooperation_score TINYINT UNSIGNED NOT NULL, strengths TEXT, improvements TEXT, final_score DECIMAL(4,2) GENERATED ALWAYS AS ((attendance_score+quality_score+productivity_score+cooperation_score)/4) STORED, notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE, FOREIGN KEY(reviewer_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE trainings (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employee_id INT UNSIGNED NOT NULL, course_name VARCHAR(150) NOT NULL, provider VARCHAR(150), starts_on DATE, ends_on DATE, status ENUM('planned','ongoing','completed') NOT NULL DEFAULT 'planned', certificate_path VARCHAR(255), certificate_expires_on DATE, FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE);
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, title VARCHAR(160) NOT NULL, body VARCHAR(255), url VARCHAR(255), read_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(user_id,read_at), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE notification_events (event_key VARCHAR(190) PRIMARY KEY, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE alert_rules (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, kind ENUM('contract','document','training') NOT NULL, days_before SMALLINT NOT NULL, notify_admin TINYINT(1) NOT NULL DEFAULT 1, notify_hr TINYINT(1) NOT NULL DEFAULT 1, notify_employee TINYINT(1) NOT NULL DEFAULT 1, active TINYINT(1) NOT NULL DEFAULT 1, UNIQUE(kind,days_before));
CREATE TABLE backup_checks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, filename VARCHAR(255) NOT NULL, checked_at DATETIME NOT NULL, status ENUM('passed','failed') NOT NULL, details VARCHAR(255) NULL);
CREATE TABLE activity_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, action VARCHAR(80) NOT NULL, entity VARCHAR(60), entity_id BIGINT UNSIGNED, details VARCHAR(255), ip_address VARCHAR(45), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(created_at), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE settings (setting_key VARCHAR(80) PRIMARY KEY, setting_value TEXT NOT NULL);
